CREATE DATABASE IF NOT EXISTS studysync_db;
USE studysync_db;
CREATE TABLE IF NOT EXISTS users (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS study_groups (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,subject VARCHAR(120) NOT NULL,description VARCHAR(500),code VARCHAR(20) UNIQUE NOT NULL,owner_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS group_members (group_id INT NOT NULL,user_id INT NOT NULL,PRIMARY KEY(group_id,user_id),FOREIGN KEY(group_id) REFERENCES study_groups(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notes (id INT PRIMARY KEY AUTO_INCREMENT,group_id INT NOT NULL,author_id INT NOT NULL,title VARCHAR(200) NOT NULL,content TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(group_id) REFERENCES study_groups(id) ON DELETE CASCADE,FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attendance (id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,subject VARCHAR(120) NOT NULL,attended INT NOT NULL,total INT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
